class BalanceChecker {
    boolean canWithdraw(BigDecimal balance, BigDecimal amount) {
        // compareTo: value-based, scale-independent (1.0 == 1.00)
        return balance.compareTo(amount) >= 0;
    }
    boolean isPositive(BigDecimal b) {
        return b.compareTo(BigDecimal.ZERO) > 0;
    }
    // CORRECT key store: TreeMap uses compareTo → 1.0 & 1.00 merge
    NavigableMap<BigDecimal, Tier> tiers = new TreeMap<>();

    // WRONG: HashMap uses equals()+hashCode → 1.0 ≠ 1.00 (two keys!)
    // Map<BigDecimal,Tier> bad = new HashMap<>();  // scale bug

    BigDecimal normalize(BigDecimal b) {
        return b.setScale(2, RoundingMode.HALF_EVEN);  // fix scale
    }
}
